        return "\n".join(rows)
    if isinstance(value, list):
        if not value:
            return pad + "[]"
        rows = []
        for v in value:
            if isinstance(v, (dict, list)) and v:
                rows.append(pad + "-\n" + _yaml(v, indent + 2))
            else:
                rows.append(pad + "- " + _yaml(v, indent + 2).lstrip())
        return "\n".join(rows)
    if value is None:
