def _reference_key_order(value, orders, path=""):
    if isinstance(value, dict):
        keys = orders.get(path, [])
        ordered = [key for key in keys if key in value]
        ordered.extend(key for key in value if key not in ordered)
        return {key: _reference_key_order(value[key], orders, path + "/" + key)
                for key in ordered}
    if isinstance(value, list):
        return [_reference_key_order(item, orders, path + "/" + str(i))
                for i, item in enumerate(value)]
    return value


def _missing_template_error(template, name, data):
    """Return the Go-template style error for a missing dotted data field."""
    pattern = re.compile(r"{{\s*(?:if\s+)?(\.[A-Za-z_][\w.]*)")
    for match in pattern.finditer(template):
        expr = match.group(1)
        value = data
        missing = None
        for key in expr[1:].split("."):
            if isinstance(value, dict) and key in value:
                value = value[key]
            else:
                missing = key
                break
        if missing is not None:
            line = template.count("\n", 0, match.start()) + 1
            previous = template.rfind("\n", 0, match.start())
            column = match.start(1) - previous - 1
            return (f'chezmoi: template: {name}:{line}:{column}: executing "{name}" at '
                    f'<{expr}>: map has no entry for key "{missing}"\n')
    return None


