"""Archive generation for the chezmoi-compatible command line."""
import gzip
import io
import json
import os
import shutil
import stat
import tarfile
import time
import datetime
import zipfile
from pathlib import Path


def _target_name(name: str) -> str | None:
    """Decode the common chezmoi source-state filename prefixes."""
    parts = []
    for part in name.split("/"):
        if part.startswith(".chezmoi") or part in (".git", ".gitignore"):
            return None
        while True:
            for prefix in ("private_", "executable_", "readonly_", "create_", "modify_", "remove_",
                           "symlink_", "exact_", "empty_", "run_once_", "run_onchange_", "run_"):
                if part.startswith(prefix):
                    part = part[len(prefix):]
                    break
            else:
                break
        if part.startswith("dot_"):
            part = "." + part[4:]
        if part.endswith(".tmpl"):
            part = part[:-5]
        parts.append(part)
    return "/".join(parts)


def _entries(src: Path):
    ignored = set()
    ignore_file = src / ".chezmoiignore"
    if ignore_file.is_file():
        ignored = {line.strip() for line in ignore_file.read_text().splitlines()
                   if line.strip() and not line.lstrip().startswith("#")}
    found = []
    for root, dirs, files in os.walk(src, followlinks=False):
        dirs[:] = sorted(d for d in dirs if d != ".git")
        for name in sorted(dirs + files):
            path = Path(root) / name
            rel = path.relative_to(src).as_posix()
            target = _target_name(rel)
            if target is not None and target not in ignored and not any(target.startswith(x.rstrip("/") + "/") for x in ignored):
                found.append((path, target))
    yield from sorted(found, key=lambda item: item[1])


def _render_template(path: Path, src: Path) -> bytes:
    data = {}
    for name in (".chezmoidata.json",):
        try:
            data.update(json.loads((src / name).read_text()))
        except (OSError, ValueError):
            pass
    text = path.read_text()
    import re
    def replace(match):
        key = match.group(1).strip().lstrip(".")
        value = data
        for part in key.split("."):
            if not isinstance(value, dict) or part not in value:
                return ""
            value = value[part]
        return str(value)
    return re.sub(r"{{\s*([^{}]+?)\s*}}", replace, text).encode()


def make_archive(src: str, fmt: str = "tar.gz", targets=None, destination="/home/agent", recursive=True) -> bytes:
    srcpath = Path(src)
    selected = None
    if targets:
        selected = set()
        for item in targets:
            path = os.path.expanduser(item)
            if os.path.isabs(path):
                try:
                    path = os.path.relpath(path, os.path.expanduser(destination))
                except ValueError:
                    continue
            path = path.replace(os.sep, "/").removeprefix("./").strip("/")
            selected.add(path)
    entries = list(_entries(srcpath))
    if selected is not None:
        entries = [(path, target) for path, target in entries
                   if target in selected or (recursive and any(target.startswith(t.rstrip("/") + "/") for t in selected))]
    fmt = fmt.lower()
    if fmt in ("tgz", "gzip"):
        fmt = "tar.gz"
    if fmt in ("tar", "tar.gz"):
        raw = io.BytesIO()
        members = []
        with tarfile.open(fileobj=raw, mode="w", format=tarfile.USTAR_FORMAT) as tf:
            for path, target in entries:
                info = tf.gettarinfo(str(path), arcname=target)
                # chezmoi archives stamp all entries with the archive creation time.
                info.mtime = int(time.time())
                members.append((target, path, info.size, info.type))
                base = path.name
                if base.startswith("symlink_"):
                    info.type = tarfile.SYMTYPE
                    info.linkname = path.read_text().strip()
                    info.size = 0
                    info.mode = 0
                    tf.addfile(info)
                elif base.endswith(".tmpl"):
                    body = _render_template(path, srcpath)
                    info.size = len(body)
                    tf.addfile(info, io.BytesIO(body))
                elif info.isfile():
                    if base.startswith("executable_"):
                        info.mode = 0o755
                    if base.startswith("readonly_"):
                        info.mode = 0o444
                    if base.startswith("private_"):
                        info.mode = 0o600
                    with path.open("rb") as f:
                        tf.addfile(info, f)
                else:
                    tf.addfile(info)
        # Go's tar writer ends with one zero block; Python pads to 10 KiB.
        end = sum(512 + ((size + 511) // 512) * 512 if kind == tarfile.REGTYPE else 512
                  for _, _, size, kind in members) + 512
        tarbytes = bytearray(raw.getvalue()[:end])
        # Go's USTAR writer emits explicit zero device numbers in all headers.
        offset = 0
        for _, _, size, kind in members:
            header = tarbytes[offset:offset + 512]
            header[329:337] = b"0000000\0"
            header[337:345] = b"0000000\0"
            header[148:156] = b"        "
            checksum = sum(header)
            header[148:156] = f"{checksum:06o}\0 ".encode("ascii")
            tarbytes[offset:offset + 512] = header
            offset += 512 + (((size + 511) // 512) * 512 if kind == tarfile.REGTYPE else 0)
        data = bytes(tarbytes)
        if fmt == "tar.gz":
            compressed = bytearray(gzip.compress(data, compresslevel=9, mtime=int(time.time())))
            # Go's gzip writer records a neutral extra-flags byte.
            compressed[8] = 0
            return bytes(compressed)
        return data
    if fmt == "zip":
        raw = io.BytesIO()
        now = datetime.datetime.now().timetuple()[:6]
        with zipfile.ZipFile(raw, "w", zipfile.ZIP_DEFLATED) as zf:
            for path, target in entries:
                info = zipfile.ZipInfo(target, now)
                info.create_system = 3
                mode = 0o100644
                if path.name.startswith("private_"):
                    mode = 0o100600
                elif path.name.startswith("readonly_"):
                    mode = 0o100444
                elif path.name.startswith("executable_"):
                    mode = 0o100755
                if path.is_symlink():
                    mode = 0o120000
                    body = os.readlink(path).encode()
                elif path.name.startswith("symlink_"):
                    mode = 0o120000
                    body = path.read_text().strip().encode()
                elif path.name.endswith(".tmpl"):
                    body = _render_template(path, srcpath)
                elif path.is_file():
                    body = path.read_bytes()
                else:
                    info.filename = target.rstrip("/") + "/"
                    info.external_attr = (0o40755 << 16) | 0x10
                    zf.writestr(info, b"")
                    continue
                info.compress_type = zipfile.ZIP_STORED if mode & 0o170000 == 0o120000 else zipfile.ZIP_DEFLATED
                info.external_attr = mode << 16
                zf.writestr(info, body)

